    name: '农业主义',
    initial: 'N',
    desc: '农业主义（Agrarianism，又译农本主义）认为务农的乡村生活优于城市生活，独立耕作的自耕农是公民德性与社会自立的根基。土地在它这里不只是谋生的工具，也是社会价值与秩序的支点。\n\n它主张「耕者有其田」，反对少数人垄断土地，也批评过快的工业化与城市化带来的贫富分化和道德涣散。亚里士多德在《政治学》里就说过，农民是最好的民众；杰斐逊把自耕农看作共和国的基石；十九世纪俄国的民粹派，以及中国的梁漱溟、晏阳初的乡村建设运动，也都带着这一脉的影子。今天的土地改革、可持续发展与「乡村振兴」讨论里，仍能听到它的回声。',
