    initial: 'M',
    desc: '冒险主义（又称盲动主义），是「左」倾机会主义的一种表现：不顾客观条件与群众觉悟，夸大自身力量、轻视对手和困难，用孤注一掷的激进行动代替冷静的评估，急于求成、硬干硬拼。列宁早在 1902 年的《革命冒险主义》里，就批评过脱离群众、只求一时轰动的做法。\n\n在中国共产党的历史上，瞿秋白时期的「左」倾盲动主义、李立三路线和王明路线，先后被认定为「左」倾冒险主义。毛泽东在《中国革命战争的战略问题》中，把第五次反「围剿」中的错误概括为军事冒险主义、军事保守主义与逃跑主义三个阶段，后来常被凝练成「进攻中的冒险主义，防御中的保守主义，退却中的逃跑主义」。它须与「冒险精神」区分开：前者是脱离实际的盲目冒进，后者是在可控风险下的果敢探索。',
