        id: 'adventure-huren',
        name: '虎刃',
        initial: 'H',
        bio: "虎刃在黑岩路矿区的车站和矿井之间来回跑，哪一班工人想停工，哪一条铁路要被堵，她往往比工会先知道。嗓门大，说话快，一句话就能把一群人从工棚里叫出来。矿上的账房说她是个麻烦，工人却愿意跟她走，因为她自己也会上前承担风险；也有工友担心，她把大家带出去以前，并没问够有多少人愿意跟。\n\n她十五岁下井，跟着一个老矿工学看瓦斯，也学看人。有一年冬天，几家工人的工钱拖到了年关，孩子买不起煤，她第二天交班时带头把两条线停了。那次没备够接济，也没等邻近班组表态，只撑了三天便散了。她被矿上开除，同去的几户人还断了收入。她仍认为不能一直等，提起那几户人时却会停一停，不再只讲当时多痛快。\n\n她和康妮在夜校和互助会里碰过几次面，理念相去不远，分歧在快慢上。康妮要先凑钱办合作社、把章程写细、把账算清，她却觉得拖一个月，工钱又少一截，等人都齐了，工友早就散到别的矿上去了。她说话难听，每次有人被欠薪，她都会第一个冲到账房门口，也会回头嫌康妮的章程太慢。",
