    id: 'egalitarianism',
    name: '平等主义',
    initial: 'P',
    desc: '平等主义（Egalitarianism）主张人人在道德地位上平等，法律、政治与公民权利也应当平等分配，政策不该因性别、种族、阶级或信仰而偏袒某一方。它真正追问的是：哪些不平等能被正当化，哪些必须被消除。\n\n当代的平等主义理论，以罗尔斯《正义论》的差异原则、德沃金的「资源平等」，以及阿马蒂亚·森的「能力平等」最为著名；后者把关注点从人拥有多少资源，转向人真正能做成什么。它内部又分福利平等、机会平等和结果平等，多数现代论者主张的是起点与机会的平等，而不是把一切结果拉平。它与自由至上主义的分歧，往往就落在平等与自由、过程与结果孰先孰后上。',
    cover: '',
    /* 主题：青玉绿 + 墨绿，天平纹样（scales=天平） */
