    id: 'expansionism',
    name: '扩张主义',
    initial: 'K',
    desc: '扩张主义（Expansionism）是一种意识形态，也是一类对外政策：通过军事、外交或移民等手段，扩大本国的领土、殖民地或势力范围，进而扩大政治、经济与文化上的影响。历史上许多强盛的国家，从罗马、蒙古到近代的欧洲列强，再到美国、俄国、日本，都奉行过某种形式的扩张，动机通常是资源、市场、出海口和战略缓冲带。\n\n扩张的形态会随时代变化。早期多是直接的兼并与殖民拓殖，例如十九世纪美国「昭昭天命」（Manifest Destiny）式的西进；当代则更多借助资本、技术、规则与文化来扩大影响力。批评者把它与侵略和帝国主义联系在一起，辩护者则常以生存空间、传播文明或互利共赢为理由。',
