        name: '凯瑟琳·辉光',
        initial: 'K',
        bio: "凯瑟琳在科鲁鲁古都的学宫里讲礼法史，学生多是贵族子弟和外地来的抄书人。她的第一堂课不讲法典，先讲一件事：为什么科鲁鲁的婚丧仪式、田契格式和钟声的时刻，别处都学不来。她说，一个地方的规矩若只能靠外人解释，就算不上真的懂。\n\n她从小在王城的礼法世家长大，十几岁就能背下三部注疏。二十出头时，她在两国使节的宴会上听见一位使节说科鲁鲁的一切「不过是落后的旧俗」，当场站起来反驳，事后被学宫记了一次过。她没有改口，只在之后的课上把那段话原样抄在黑板上，让学生逐句拆开看。\n\n她认为科鲁鲁独特的礼法与教会传统，足以使它不受一些通行于别国的评判约束，反对把外邦的改革章程照抄过来。学生问，同一件不公的事为何到了本国就能另论，她会拿出历史解释，却不总能说明这些历史为何足以免除今天的责任。她也会批评本国官员，唯独外人用了相同的话，常先急着反驳。",
