        id: 'interventionism-maeve',
        name: '梅芙·辛克莱',
        initial: 'M',
        bio: "梅芙是伊鲁尼利亚派出去的特使。她受命参与对外援助与危机谈判，粮船、贷款和顾问各由相应部门调度，她负责把附带的条件谈进协议。不是每场危机都能介入，也不是她签一个字就能拨钱出兵。\n\n她是真想把事情办成的，这一点和只图地盘的同僚不一样。可援助到岸的那天，条件也跟着到岸：钱由谁花，海关由谁管，下一轮谈判由哪一方出面，都要先写进协议里。\n\n说她管得太宽的人不少。她的回答很简单：人已经在那里死着，她的手不伸过去，那边的事也不会因此停下。可援助撤走以后，偿债和被改变的规矩仍留给当地人，不能靠她愿意担责便一笔勾销。",
        info: [{"k":"身份","v":"伊鲁尼利亚 · 对外事务特使"},{"k":"出生日期","v":"新历512年"},{"k":"属地","v":"伊鲁尼利亚共和国"}],
        desc: '',
