        initial: 'D',
        bio: "戴安娜在伊鲁尼利亚的国防议事厅参与对外安全事务，常替驻港、护航和军援方案争取支持。她相信小国各行其是只会让局面失控，由本国维持优势，才有她所说的秩序。\n\n谈判桌上，她会把护航与港口使用权、军援与对外立场放在一起谈。对方仍有自己的政府，拒绝的余地却常被贷款和军备依赖挤掉。她将这些条件称为共同安全，很少追问对方是不是还有别的选择。\n\n她能左右部分议案，却不能凭一句话调动舰队，预算和出兵仍须经过共和国的决策程序。碰上反对者，会耐着性子改措辞、换筹码；外表越平静，随员越知道她不打算轻易放手。",
