        name: '普罗塔·休曼',
        initial: 'P',
        bio: '普罗塔·休曼在坎普评议资源开发的提案。矿路通向哪片住地，河水要分给谁，工程会让多少人迁走，她都会问。她对人改造大地有很强的信心，认为林木、河流与矿藏应当为人的生活服务，判断好坏，先看它们怎样影响人。\n\n这也使她重视水源与林地的长远保存。她反对把上游弄脏、把沿岸砍空，理由是下游的人要喝水，后来的孩子也要有地方住。倘若一处自然景观必须改变才能保障居民，她愿意支持施工；有人说那片生境本身也值得保留，她会要求先讲清这样做对人有什么意义。她的关怀很广，却始终把人放在最前面。\n\n普罗塔说话笃定，容易相信一张画得完善的图纸已替大家想周全。去到工棚，听见住户说搬家以后取水更远，她才会让人把提案退回来核实。闲时爱看新开的学校和工坊，碰到学徒做成第一件像样的东西，常站着听很久，临走又问下一件准备做什么。',
