        id: 'stalinism-yekaterina',
        name: '叶卡捷琳娜·朱加什维利',
        initial: 'Y',
        bio: "叶卡捷琳娜在铁枢中央计划委员会任主任。铁路、钢厂与集体农庄在她任职前就已建立，她接手的是一套正在扩大的计划体系。委员会拟定生产与供给目标，由有关机构议定后交各部门执行；地方报来的缺口和调整请求，又集中到她的桌前。\n\n她主张先巩固本国工业与防卫，把有限的资源优先投向重工业，民用供给可以暂时让路。部门各有难处，她更相信中央统一安排，不愿让地方自行削减指标。报表迟迟不好看，她容易把材料短缺和消极抵制混在一起，要求追查责任，再把疑点交纪律机关处理。\n\n她愿意听技术上的反驳，却常把对决策权的质疑看成不忠。委员会的宣传越来越突出她的名字，她没有制止；下属也逐渐学会先报好消息。她为掌握真实产量反复催报，自己造成的压力却使人更不敢讲实情。\n\n叶卡捷琳娜记性好，会议上不喜欢别人绕弯。过于整齐的数字仍会引起她的疑心，只是她首先想到的总是有人隐瞒，而很少想到该给不同意见留出不受处罚的余地。",
        info: [{ k: '身份', v: '铁枢人民共和国 · 中央计划委员会主任' }, { k: '出生日期', v: '新历515年' }, { k: '属地', v: '铁枢人民共和国' }],
