        name: '西蒙娜·萨特',
        initial: 'X',
        bio: '西蒙娜在万知城的旧城区租了一间屋子，每天上午坐在同一张桌前写东西，写到中午为止。小说，随笔，题目都很普通，一条街，一顿晚饭，一个下午。今天写得顺不顺，第二天她照样坐回去。\n\n她对不上号的地方不少。别人为一场辩论争得面红耳赤，她在旁边看着，觉得热闹，却插不进去；该表示悲伤或热情的场合，没有就是没有，她也懒得装。朋友说她不会应付场面，她点点头，没打算学。\n\n人想要意义，世界却不吭声，这一点她看得很清楚。教会给的答案她没接，想一了百了的念头也没有，日子照常过。她更在意窗外的光落在哪块地板上，晚饭的汤够不够热。读她书的人常说冷，不少人读完，第二天还是愿意出门。',
        info: [{"k":"身份","v":"万知城 · 小说家与随笔作者"},{"k":"出生日期","v":"新历516年"},{"k":"属地","v":"万知城"}],
