        bio: "亨丽埃塔出身塞雷格的军政世家，任帝国秩序署长官。她把国家复兴看成压倒个人与党派的目标，认定争论、独立结社和劳资冲突会削弱整个帝国。\n\n秩序署管宣传、团体登记和集会整肃。她要求各行业与青年组织接受统一训导，用游行、仪典和军人榜样培养对统治中心的效忠；不肯加入的人，也会被列入需查问的名单。整齐的名册背后，有被解散的社团、被查禁的刊物和失去工作的异议者。\n\n她很少发火，下令查封时也像核一份普通公文。对下属的照顾是真实的，对受压者的处境却惯于以国家需要作答。军队、财政和宫廷各有掌权者，她不能独占国政，但会不断要求把更多事务划入秩序署。",
        info: [ { k: '身份', v: '塞雷格 · 帝国秩序署长官' }, { k: '出生日期', v: '新历507年' }, { k: '属地', v: '塞雷格帝国' } ],
